/* com.portal.user.poll.qim.QustnrItemManageMapper.updateQustnrItemManage */
UPDATE LETTNQUSTNRIEM
SET
	IEM_SN          = #{iemSn},
	IEM_CN          = #{iemCn},
	ETC_ANSWER_AT   = #{etcAnswerAt},
	LAST_UPDT_PNTTM = sysdate(),
	LAST_UPDUSR_ID  = #{lastUpdusrId}
WHERE QUSTNR_IEM_ID = #{qustnrIemId}

mapper.select:
/* com.portal.user.poll.qim.QustnrItemManageMapper.selectQustnrItemManageList */ SELECT A.QUSTNR_QESITM_ID AS qestnrQesitmId, A.QESTNR_ID AS QESTNR_ID, A.IEM_SN, A.QUSTNR_IEM_ID, A.IEM_CN, A.ETC_ANSWER_AT, A.QUSTNR_TMPLAT_ID AS qestnrTmplatId, DATE_FORMAT(A.FRST_REGIST_PNTTM, '%Y-%m-%d') AS FRST_REGIST_PNTTM, A.FRST_REGISTER_ID, (SELECT USER_NM FROM COMVNUSERMASTER WHERE ESNTL_ID = A.FRST_REGISTER_ID) AS FRST_REGISTER_NM, DATE_FORMAT(A.LAST_UPDT_PNTTM, '%Y-%m-%d') AS LAST_UPDT_PNTTM, A.LAST_UPDUSR_ID FROM LETTNQUSTNRIEM A WHERE 1=1
AND A.IEM_CN LIKE CONCAT('%', #{searchKeyword}, '%')
AND A.FRST_REGISTER_ID IN ( SELECT ESNTL_ID FROM COMVNUSERMASTER WHERE USER_NM LIKE CONCAT('%', #{searchKeyword}, '%') )
ORDER BY A.FRST_REGIST_PNTTM DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

/* com.portal.user.poll.qim.QustnrItemManageMapper.selectQustnrItemManageListCnt */ SELECT COUNT(*) AS totcnt FROM LETTNQUSTNRIEM WHERE 1=1
AND IEM_CN LIKE CONCAT('%', #{searchKeyword}, '%')
AND FRST_REGISTER_ID IN ( SELECT ESNTL_ID FROM COMVNUSERMASTER WHERE USER_NM LIKE CONCAT('%', #{searchKeyword}, '%') )
